function unpack(s) {
  const t = s.replace(/\s+/g, '');
  const out = new Array(t.length / 5);
  for (let i = 0; i < out.length; i++) out[i] = t.slice(i * 5, i * 5 + 5);
  return out;
}

let answers = null;
let valid = null;

/** Alphabetical list of possible answers (lowercase). */
export function getAnswers() {
  if (!answers) answers = unpack(A);
  return answers;
}

/** Set of every accepted guess (lowercase), answers included. */
export function getValid() {
  if (!valid) {
    valid = new Set(getAnswers());
    for (const w of unpack(E)) valid.add(w);
  }
  return valid;
}
